-- CareerPilot targeted JD data patch
-- Generated from the local PostgreSQL database on 2026-10-14.
-- Repairs job IDs: 92, 94, 97, 98, 99, 107, 270, 274, 275, 278, 280, 282, 283, 344.
-- Apply only after running the repository's current Alembic migrations.

\set ON_ERROR_STOP on
BEGIN;

CREATE TEMP TABLE _patch_companies (
    id bigint,
    industry_id bigint,
    updated_at timestamptz
) ON COMMIT DROP;
CREATE TEMP TABLE _patch_skills (
    canonical_name text,
    normalized_name text,
    category text,
    created_at timestamptz
) ON COMMIT DROP;
CREATE TEMP TABLE _patch_job_postings AS
SELECT id, company_id, source_id, external_id, title, location_text,
       source_employment_type, source_url, status, inactive_reason,
       first_seen_at, last_seen_at, created_at, updated_at, description,
       content_hash, raw_payload, collected_at
FROM job_postings WITH NO DATA;
CREATE TEMP TABLE _patch_job_analyses AS
SELECT job_id, summary, employment_type, candidate_type, remote_policy,
       degree_required, raw_analysis, created_at
FROM job_analyses WITH NO DATA;
CREATE TEMP TABLE _patch_job_responsibilities AS
SELECT job_id, sequence_no, responsibility_text, embedding, embedding_model,
       embedding_content_hash, embedded_at
FROM job_responsibilities WITH NO DATA;
CREATE TEMP TABLE _patch_job_skill_requirements (
    job_id bigint,
    skill_canonical_name text,
    requirement_type text,
    sequence_no integer,
    source_text text
) ON COMMIT DROP;
CREATE TEMP TABLE _patch_job_roles (
    job_id bigint,
    role_canonical_name text,
    rank smallint,
    similarity numeric,
    model_name text,
    algorithm_version text,
    input_hash character(64),
    taxonomy_hash character(64),
    matched_at timestamptz
) ON COMMIT DROP;








UPDATE companies c
SET industry_id = p.industry_id,
    updated_at = p.updated_at
FROM _patch_companies p
WHERE c.id = p.id;

SELECT canonical_name, normalized_name, category, created_at
FROM _patch_skills
ON CONFLICT (normalized_name) DO UPDATE
SET canonical_name = EXCLUDED.canonical_name,
    category = COALESCE(skills.category, EXCLUDED.category);

    id, company_id, source_id, external_id, title, location_text,
    source_employment_type, source_url, status, inactive_reason,
    first_seen_at, last_seen_at, created_at, updated_at, description,
    content_hash, raw_payload, collected_at
)
SELECT id, company_id, source_id, external_id, title, location_text,
       source_employment_type, source_url, status, inactive_reason,
       first_seen_at, last_seen_at, created_at, updated_at, description,
       content_hash, raw_payload, collected_at
FROM _patch_job_postings
ON CONFLICT (id) DO UPDATE SET
    company_id = EXCLUDED.company_id,
    source_id = EXCLUDED.source_id,
    external_id = EXCLUDED.external_id,
    title = EXCLUDED.title,
    location_text = EXCLUDED.location_text,
    source_employment_type = EXCLUDED.source_employment_type,
    source_url = EXCLUDED.source_url,
    status = EXCLUDED.status,
    inactive_reason = EXCLUDED.inactive_reason,
    first_seen_at = EXCLUDED.first_seen_at,
    last_seen_at = EXCLUDED.last_seen_at,
    created_at = EXCLUDED.created_at,
    updated_at = EXCLUDED.updated_at,
    description = EXCLUDED.description,
    content_hash = EXCLUDED.content_hash,
    raw_payload = EXCLUDED.raw_payload,
    collected_at = EXCLUDED.collected_at;

DELETE FROM job_roles
WHERE job_id IN (SELECT id FROM _patch_job_postings);
DELETE FROM job_responsibilities
WHERE job_id IN (SELECT id FROM _patch_job_postings);
DELETE FROM job_skill_requirements
WHERE job_id IN (SELECT id FROM _patch_job_postings);
DELETE FROM job_analyses
WHERE job_id IN (SELECT id FROM _patch_job_postings);

    job_id, summary, employment_type, candidate_type, remote_policy,
    degree_required, raw_analysis, created_at
)
SELECT job_id, summary, employment_type, candidate_type, remote_policy,
       degree_required, raw_analysis, created_at
FROM _patch_job_analyses;

    job_id, sequence_no, responsibility_text, embedding, embedding_model,
    embedding_content_hash, embedded_at
)
SELECT job_id, sequence_no, responsibility_text, embedding, embedding_model,
       embedding_content_hash, embedded_at
FROM _patch_job_responsibilities;

    job_id, skill_id, requirement_type, sequence_no, source_text
)
SELECT p.job_id, s.id, p.requirement_type, p.sequence_no, p.source_text
FROM _patch_job_skill_requirements p
JOIN skills s ON s.canonical_name = p.skill_canonical_name;

    job_id, role_id, rank, similarity, model_name, algorithm_version,
    input_hash, taxonomy_hash, matched_at
)
SELECT p.job_id, r.id, p.rank, p.similarity, p.model_name,
       p.algorithm_version, p.input_hash, p.taxonomy_hash, p.matched_at
FROM _patch_job_roles p
JOIN roles r ON r.canonical_name = p.role_canonical_name;

DO $$
DECLARE
    posting_count integer;
    analysis_count integer;
    responsibility_count integer;
    requirement_count integer;
    role_count integer;
BEGIN
    SELECT count(*) INTO posting_count FROM job_postings
    WHERE id IN (92,94,97,98,99,107,270,274,275,278,280,282,283,344);
    SELECT count(*) INTO analysis_count FROM job_analyses
    WHERE job_id IN (92,94,97,98,99,107,270,274,275,278,280,282,283,344);
    SELECT count(*) INTO responsibility_count FROM job_responsibilities
    WHERE job_id IN (92,94,97,98,99,107,270,274,275,278,280,282,283,344);
    SELECT count(*) INTO requirement_count FROM job_skill_requirements
    WHERE job_id IN (92,94,97,98,99,107,270,274,275,278,280,282,283,344);
    SELECT count(*) INTO role_count FROM job_roles
    WHERE job_id IN (92,94,97,98,99,107,270,274,275,278,280,282,283,344);

    IF posting_count <> 14 OR analysis_count <> 14
       OR responsibility_count <> 98 OR requirement_count <> 159
       OR role_count <> 42 THEN
        RAISE EXCEPTION
            'JD patch validation failed: postings %, analyses %, responsibilities %, requirements %, roles %',
            posting_count, analysis_count, responsibility_count,
            requirement_count, role_count;
    END IF;
END $$;

COMMIT;
